vec3 retX0 = texture(sampler_main,uv) + 2.0*GetBlur2 (uv);
vec3 retX1 = texture(sampler_main,uvX) + 2.0*GetBlur2 (uvX);
vec3 retZ1 = retX0 + retX1  ;
vec3 retZ2 = retX0 * retX1  ;
vec3 retMIX1 = mix(retZ2, retZ1, q29 * .16);
ret = mix(ret,retMIX1,q29 * .5);
vec3 retI = 1.0 - ret;
//retI += .2;
